def find_in_ring(ring, targets):
    where = {v: i for i, v in enumerate(ring)}
    top = max(ring) if ring else None
    out = []
    for t in targets:
        if top is None or t > top:
            out.append(-1)
            continue
        while t not in where:
            t += 1
        out.append(where[t])
    return out
